WHERE member.company_id = #{f.companyId}
AND member.operator_type != 'promoter'

	AND member.member_type = #{f.memberType}


	AND member.operator_type = #{f.operatorType}


	AND (corp.legal_person = #{f.keywordsEnc}
	OR member.user_name = #{f.keywordsEnc}
	OR member.location = #{f.keywordsPlain})
